// Where the selection lands after a close: closing a tab left of the
// selected one shifts it down, then clamp into the shorter list.
static int SelectionAfterClose(int selected, int closed, int remaining) =>
    remaining == 0 ? -1 : Math.Clamp(closed < selected ? selected - 1 : selected, 0, remaining - 1);

var (tabs, setTabs) = UseState(UseMemo(() => new[] { "Home", "Document", "Settings" }));
var (idx, setIdx) = UseState(0);

TabView(tabs.Select(t => Tab(t, TextBlock($"{t} content").Padding(16))).ToArray()) with
{
    SelectedIndex = idx,
    OnSelectedIndexChanged = i => setIdx(i),
    // The per-tab ✕ only raises TabCloseRequested — the app removes the tab, and
    // must also pull the selection back into range.
    OnTabCloseRequested = i =>
    {
        var remaining = tabs.Where((_, n) => n != i).ToArray();
        setTabs(remaining);
        setIdx(SelectionAfterClose(idx, i, remaining.Length));
    },
}

